import { InjectionToken, Type } from '@angular/core';
import { Observable } from 'rxjs';

declare const WA_ANIMATION_FRAME: InjectionToken<Observable<number>>;

declare const WA_CACHES: InjectionToken<CacheStorage>;

declare const WA_CRYPTO: InjectionToken<Crypto>;

declare global {
    interface Window {
        CSS: typeof CSS | null;
    }
}
declare const WA_CSS: InjectionToken<typeof CSS>;

declare const WA_HISTORY: InjectionToken<History>;

declare const WA_LOCAL_STORAGE: InjectionToken<Storage | null>;

declare const WA_LOCATION: InjectionToken<Location>;

declare const WA_MEDIA_DEVICES: InjectionToken<MediaDevices>;

declare const WA_NAVIGATOR: InjectionToken<Navigator>;

type ConnectionType = 'bluetooth' | 'cellular' | 'ethernet' | 'mixed' | 'none' | 'other' | 'unknown' | 'wifi' | 'wimax';
type EffectiveConnectionType = '2g' | '3g' | '4g' | 'slow-2g';
type Megabit = number;
type Millisecond = number;
interface NetworkInformation extends EventTarget {
    readonly type?: ConnectionType;
    readonly effectiveType?: EffectiveConnectionType;
    readonly downlinkMax?: Megabit;
    readonly downlink?: Megabit;
    readonly rtt?: Millisecond;
    readonly saveData?: boolean;
    onchange?: EventListener;
}
declare const WA_NETWORK_INFORMATION: InjectionToken<NetworkInformation | null>;

declare const WA_PAGE_VISIBILITY: InjectionToken<Observable<boolean>>;

declare const WA_PERFORMANCE: InjectionToken<Performance>;

declare const WA_SCREEN: InjectionToken<Screen>;

declare const WA_SESSION_STORAGE: InjectionToken<Storage | null>;

declare global {
    /**
     * Workaround:
     * This empty interface prevents TS errors when a consumer has
     * `skipLibCheck: false` and did not include `dom-speech-recognition`
     * in `tsconfig.types`.
     *
     * The real `SpeechRecognition` interface is provided by
     * `@types/dom-speech-recognition` when it is present.
     */
    interface SpeechRecognition {
    }
}
declare const WA_SPEECH_RECOGNITION: InjectionToken<Type<SpeechRecognition> | null>;

declare const WA_SPEECH_SYNTHESIS: InjectionToken<SpeechSynthesis>;

declare const WA_USER_AGENT: InjectionToken<string>;

declare const WA_WINDOW: InjectionToken<Window>;

declare function waInjectElement<T = HTMLElement>(): T;

export { WA_ANIMATION_FRAME, WA_CACHES, WA_CRYPTO, WA_CSS, WA_HISTORY, WA_LOCAL_STORAGE, WA_LOCATION, WA_MEDIA_DEVICES, WA_NAVIGATOR, WA_NETWORK_INFORMATION, WA_PAGE_VISIBILITY, WA_PERFORMANCE, WA_SCREEN, WA_SESSION_STORAGE, WA_SPEECH_RECOGNITION, WA_SPEECH_SYNTHESIS, WA_USER_AGENT, WA_WINDOW, waInjectElement };
